import re
import uuid
from pathlib import Path

from fastapi import APIRouter, Depends, File, UploadFile
from fastapi.responses import FileResponse

from app.config import config
from app.core.errors import AppError
from app.modules.auth.dependencies import current_user
from app.modules.auth.models import User

file_flow_router = APIRouter()

UPLOAD_DIR = Path(config.FILES_DIR)
MAX_SIZE = config.FILES_MAX_SIZE_MB * 1024 * 1024
CHUNK_SIZE = 1024 * 1024
# Stored names are generated by the server, so only this shape is ever served.
STORED_NAME = re.compile(r"^[0-9a-f]{32}(\.[A-Za-z0-9]{1,10})?$")


@file_flow_router.post("/upload")
async def upload_file(
    file: UploadFile = File(...),
    user: User = Depends(current_user),
):
    UPLOAD_DIR.mkdir(parents=True, exist_ok=True)
    suffix = Path(file.filename or "").suffix.lower()
    if not re.fullmatch(r"\.[a-z0-9]{1,10}", suffix):
        suffix = ""
    stored_name = f"{uuid.uuid4().hex}{suffix}"
    target = UPLOAD_DIR / stored_name

    size = 0
    with target.open("wb") as buffer:
        while chunk := await file.read(CHUNK_SIZE):
            size += len(chunk)
            if size > MAX_SIZE:
                buffer.close()
                target.unlink(missing_ok=True)
                raise AppError(413, "file_too_large", max_mb=config.FILES_MAX_SIZE_MB)
            buffer.write(chunk)

    return {
        "filename": file.filename,
        "stored_name": stored_name,
        "url": f"/api/v1/file_flow/download/{stored_name}",
    }


@file_flow_router.get("/download/{stored_name}")
async def download_file(stored_name: str):
    path = UPLOAD_DIR / stored_name
    if not STORED_NAME.fullmatch(stored_name) or not path.is_file():
        raise AppError(404, "file_not_found")
    return FileResponse(path)
